'use client';

import {
  type CodePlugin,
  type EditorLeafProps,
  EditorLeaf,
} from 'platejs/react';
import * as React from 'react';

export function CodeLeaf(props: EditorLeafProps<typeof CodePlugin>) {
  return (
    <EditorLeaf
      {...props}
      as="code"
      className="rounded-md bg-muted px-[0.3em] py-[0.2em] font-mono text-sm whitespace-pre-wrap"
    >
      {props.children}
    </EditorLeaf>
  );
}
